        } else {
            println("  FAIL: ESS exceeds n_samples")
            failed = failed + 1
        }
    } else {
        println("  FAIL: ESS too low")
        failed = failed + 1
    }
    println("")

    // ================================================================
    // TEST 6: Normal prior log-density
    // ================================================================

    println("TEST 6: Normal log-density")
    let lp_norm = normal_log_density(0.0, 0.0, 1.0)
    let expected_lp = 0.0 - 0.9189385332046727
    let err_lp = abs_f64(lp_norm - expected_lp)
    println("  log N(0|0,1) (expected -0.9189):")
    println(lp_norm)

    let lp_norm_1 = normal_log_density(1.0, 0.0, 1.0)
    let expected_lp_1 = 0.0 - 1.4189385332046727
    let err_lp_1 = abs_f64(lp_norm_1 - expected_lp_1)

    if err_lp < 0.01 {
        if err_lp_1 < 0.01 {
            println("  [PASS] Normal log-density correct")
            passed = passed + 1
        } else {
            println("  FAIL: Normal log-density at x=1 incorrect")
            failed = failed + 1
        }
    } else {
        println("  FAIL: Normal log-density at x=0 incorrect")
        failed = failed + 1
    }
    println("")

    // ================================================================
    // TEST 7: Uniform prior log-density
    // ================================================================

    println("TEST 7: Uniform log-density")
    let lp_unif = uniform_log_density(5.0, 0.0, 10.0)
    let expected_unif = 0.0 - ln_f64(10.0)
    let err_unif = abs_f64(lp_unif - expected_unif)

    let lp_unif_out = uniform_log_density(11.0, 0.0, 10.0)

    println("  log U(5|0,10) (expected -2.3026):")
    println(lp_unif)

    if err_unif < 0.01 {
        if lp_unif_out < 0.0 - 1.0e20 {
            println("  [PASS] Uniform log-density correct")
            passed = passed + 1
        } else {
            println("  FAIL: Uniform should be -inf outside support")
            failed = failed + 1
        }
    } else {
        println("  FAIL: Uniform log-density value incorrect")
        failed = failed + 1
    }
    println("")

    // ================================================================
    // TEST 8: Gamma prior log-density
    // ================================================================

    println("TEST 8: Gamma log-density")
    let lp_gamma = gamma_log_density(1.0, 2.0, 1.0)
    let err_gamma = abs_f64(lp_gamma - (0.0 - 1.0))
    println("  log Gamma(1|2,1) (expected -1.0):")
    println(lp_gamma)

    let lp_gamma_neg = gamma_log_density(0.0 - 1.0, 2.0, 1.0)

    if err_gamma < 0.05 {
        if lp_gamma_neg < 0.0 - 1.0e20 {
            println("  [PASS] Gamma log-density correct")
            passed = passed + 1
        } else {
            println("  FAIL: Gamma should be -inf for x<0")
            failed = failed + 1
        }
    } else {
        println("  FAIL: Gamma log-density value incorrect")
        println(err_gamma)
        failed = failed + 1
    }
    println("")

    // ================================================================
    // TEST 9: Knowledge conversion from chain
    // ================================================================

    println("TEST 9: Chain to BayesianKnowledge")
    var know = BayesianKnowledge { mean: 0.0, std_dev: 0.0, ci_lower: 0.0, ci_upper: 0.0, confidence: 0.0, n_effective: 0.0 }
    chain_to_knowledge_into(&!know, &chain4)
    println("  Knowledge mean (target ~3.0):")
    println(know.mean)
    println("  Knowledge std_dev (target ~1.0):")
    println(know.std_dev)
    println("  95% CI lower:")
    println(know.ci_lower)
    println("  95% CI upper:")
    println(know.ci_upper)
    println("  Confidence:")
    println(know.confidence)
    println("  Effective N:")
    println(know.n_effective)

    let err_know_mean = abs_f64(know.mean - 3.0)
    let ci_contains_lower = know.ci_lower < 3.0
    let ci_contains_upper = know.ci_upper > 3.0
    let conf_ok = know.confidence >= 0.5

    if err_know_mean < 0.3 {
        if ci_contains_lower {
            if ci_contains_upper {
                if conf_ok {
                    println("  [PASS] BayesianKnowledge conversion correct")
                    passed = passed + 1
                } else {
                    println("  FAIL: Confidence too low")
                    failed = failed + 1
                }
            } else {
                println("  FAIL: CI upper bound does not contain target")
                failed = failed + 1
            }
        } else {
            println("  FAIL: CI lower bound does not contain target")
            failed = failed + 1
        }
    } else {
        println("  FAIL: Knowledge mean too far from 3.0")
        failed = failed + 1
    }
    println("")

    // ================================================================
    // TEST 10: Convergence confidence scoring
    // ================================================================

    println("TEST 10: Convergence confidence scoring")

    let conf1 = convergence_confidence(500.0, 1.01)
    let conf2 = convergence_confidence(200.0, 1.08)
    let conf3 = convergence_confidence(50.0, 1.20)

    println("  Tier 1 (ESS=500, R-hat=1.01):")
    println(conf1)
    println("  Tier 2 (ESS=200, R-hat=1.08):")
    println(conf2)
    println("  Tier 3 (ESS=50, R-hat=1.20):")
    println(conf3)

    var conf_test_ok = true
    if conf1 < 0.95 {
        println("  FAIL: Tier 1 confidence should be >= 0.95")
        conf_test_ok = false
    }
    if conf2 < 0.80 {
        println("  FAIL: Tier 2 confidence should be >= 0.80")
        conf_test_ok = false
    }
    if conf2 >= 0.95 {
        println("  FAIL: Tier 2 confidence should be < 0.95")
        conf_test_ok = false
    }
    if conf3 < 0.5 {
        println("  FAIL: Tier 3 confidence should be >= 0.5")
        conf_test_ok = false
    }
    if conf3 >= 0.80 {
        println("  FAIL: Tier 3 confidence should be < 0.80")
        conf_test_ok = false
    }

    if conf_test_ok {
        println("  [PASS] Convergence confidence tiers correct")
        passed = passed + 1
    } else {
        failed = failed + 1
    }
    println("")

    // ================================================================
    // SUMMARY
    // ================================================================

    println("======================================================================")
    println("  MCMC INTEGRATION TEST SUMMARY")
    println("======================================================================")
    println("  Passed:")
    println(passed)
    println("  Failed:")
    println(failed)

    if failed == 0 {
        println("  ALL 10 TESTS PASSED")
    } else {
        println("  SOME TESTS FAILED")
    }
    println("======================================================================")

    return failed
}

//@ run-pass
// Module-level `let` constants with EXPRESSION initializers must carry the folded value.
// Found 2026-09-01 through the e-graph Q-certificate self-tests: the lean_single seed read
// `0 - 1` as 0 (dropping everything after the first literal), which made EG_INVALID == 0 in
// every source-built Madaros and silently discarded the first node of every small e-graph;
// Madaros' own folder lacked shifts (`1 << 3` -> BSS zero). Every case below is checked
// against an in-function computation of the same expression.
let C_NEG: i64 = 0 - 1
let C_NEGLIT: i64 = -1
let C_SUM: i64 = 1 + 1
let C_MULP: i64 = (2 + 3) * 4
let C_PREC: i64 = 2 + 3 * 4
let C_SHL: i64 = 1 << 3
let C_SHR: i64 = 256 >> 4
let C_REM: i64 = 7 % 4
let C_AND: i64 = 6 & 3
let C_OR: i64 = 6 | 1
let C_XOR: i64 = 6 ^ 3
let C_BIG: i64 = 0 - 800001
let C_CHAIN: i64 = 0 - 1 - 1

fn main() -> i32 with IO {
    var bad: i64 = 0
    if C_NEG != 0 - 1 { println("FAIL C_NEG"); bad = bad + 1 }
    if C_NEGLIT != 0 - 1 { println("FAIL C_NEGLIT"); bad = bad + 1 }
    if C_SUM != 2 { println("FAIL C_SUM"); bad = bad + 1 }
    if C_MULP != 20 { println("FAIL C_MULP"); bad = bad + 1 }
    if C_PREC != 14 { println("FAIL C_PREC"); bad = bad + 1 }
    if C_SHL != 8 { println("FAIL C_SHL"); bad = bad + 1 }
    if C_SHR != 16 { println("FAIL C_SHR"); bad = bad + 1 }
    if C_REM != 3 { println("FAIL C_REM"); bad = bad + 1 }
    if C_AND != 2 { println("FAIL C_AND"); bad = bad + 1 }
    if C_OR != 7 { println("FAIL C_OR"); bad = bad + 1 }
    if C_XOR != 5 { println("FAIL C_XOR"); bad = bad + 1 }
    if C_BIG != 0 - 800001 { println("FAIL C_BIG"); bad = bad + 1 }
    if C_CHAIN != 0 - 2 { println("FAIL C_CHAIN"); bad = bad + 1 }
    // The e-graph consequence, in miniature: an id of 0 must NOT compare equal to the sentinel.
    let id: i64 = 0
    if id == C_NEG { println("FAIL sentinel: 0 == C_NEG"); bad = bad + 1 }
    if bad == 0 { println("module_let_const_expr: OK") }
    bad as i32
}

//@ run-pass
//@ expect-stdout: NATIVE_MATH_IMPORT_OK
//@ requires: madaros
// E221 refuses the bare `atan` because the backend cannot emit it. That refusal
// is only defensible if the alternative its help line names actually works, so
// this exercises it: import the pure-Sounio implementation and compute.
//
// It did NOT work before: `fn atan` in stdlib/math/pure.sio was not `pub`, so
// the import failed with E175 and the diagnostic pointed nowhere. Measured, and
// the reason those five gained `pub`.
use math::pure::{atan, asin, acos}

fn near(a: f64, b: f64) -> bool {
    let d = a - b
    if d < 0.0 { return 0.0 - d < 1.0e-6 }
    return d < 1.0e-6
}

fn main() with IO, Mut, Div, Panic {
    let ok = near(atan(0.5), 0.4636476090008061)
        && near(atan(2.0), 1.1071487177940904)
        && near(asin(0.5), 0.5235987755982989)
        && near(acos(0.5), 1.0471975511965979)
    if ok { print("NATIVE_MATH_IMPORT_OK\n") }
    else {
        print("NATIVE_MATH_IMPORT_FAIL\n")
        print("atan(0.5)="); print_f64(atan(0.5)); print("\n")
        print("asin(0.5)="); print_f64(asin(0.5)); print("\n")
        print("acos(0.5)="); print_f64(acos(0.5)); print("\n")
    }
}

