enum Outer {
    First,
    Second,
    Third,
}

enum Inner {
    Left,
    Right,
}

fn classify(outer: Outer, inner: Inner) -> i64 {
    match outer {
        Outer::First => {
            match inner {
                Inner::Left => 1,
                Inner::Right => 2,
            }
        }
        Outer::Second => 3,
        Outer::Third => 4,
    }
}

