// to avoid lean_single's &!Struct write-through limitation.

// =============================================================================
// Tag constants
// =============================================================================

fn TAG_CONST() -> i64 { 0 }
fn TAG_VAR() -> i64 { 1 }
fn TAG_ADD() -> i64 { 2 }
fn TAG_SUB() -> i64 { 3 }
fn TAG_MUL() -> i64 { 4 }
fn TAG_DIV() -> i64 { 5 }
fn TAG_NEG() -> i64 { 6 }
fn TAG_SIN() -> i64 { 7 }
fn TAG_COS() -> i64 { 8 }
fn TAG_EXP() -> i64 { 9 }
fn TAG_LOG() -> i64 { 10 }

// =============================================================================
// Global arena (flat arrays, BSS-allocated)
// =============================================================================

var AR_TAGS: [i64; 256] = [0; 256]
var AR_LEFT: [i64; 256] = [0; 256]
var AR_RIGHT: [i64; 256] = [0; 256]
var AR_VALS: [f64; 256] = [0.0; 256]
var AR_VIDS: [i64; 256] = [0; 256]
var AR_COUNT: i64 = 0

fn arena_reset() with Mut { AR_COUNT = 0 }

// =============================================================================
// Node constructors (operate on global arena)
// =============================================================================

fn expr_const(value: f64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 0  // TAG_CONST
    AR_LEFT[idx] = 0 - 1
    AR_RIGHT[idx] = 0 - 1
    AR_VALS[idx] = value
    AR_VIDS[idx] = 0 - 1
    AR_COUNT = AR_COUNT + 1
    idx
}

fn expr_var(var_id: i64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 1  // TAG_VAR
    AR_LEFT[idx] = 0 - 1
    AR_RIGHT[idx] = 0 - 1
    AR_VALS[idx] = 0.0
    AR_VIDS[idx] = var_id
    AR_COUNT = AR_COUNT + 1
    idx
}

fn expr_add(l: i64, r: i64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 2  // TAG_ADD
    AR_LEFT[idx] = l
    AR_RIGHT[idx] = r
    AR_VALS[idx] = 0.0
    AR_VIDS[idx] = 0 - 1
    AR_COUNT = AR_COUNT + 1
    idx
}

fn expr_sub(l: i64, r: i64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 3  // TAG_SUB
    AR_LEFT[idx] = l
    AR_RIGHT[idx] = r
    AR_VALS[idx] = 0.0
    AR_VIDS[idx] = 0 - 1
    AR_COUNT = AR_COUNT + 1
    idx
}

fn expr_mul(l: i64, r: i64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 4  // TAG_MUL
    AR_LEFT[idx] = l
    AR_RIGHT[idx] = r
    AR_VALS[idx] = 0.0
    AR_VIDS[idx] = 0 - 1
    AR_COUNT = AR_COUNT + 1
    idx
}

fn expr_div(l: i64, r: i64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 5  // TAG_DIV
    AR_LEFT[idx] = l
    AR_RIGHT[idx] = r
    AR_VALS[idx] = 0.0
    AR_VIDS[idx] = 0 - 1
    AR_COUNT = AR_COUNT + 1
    idx
}

fn expr_neg(child: i64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 6  // TAG_NEG
    AR_LEFT[idx] = child
    AR_RIGHT[idx] = 0 - 1
    AR_VALS[idx] = 0.0
    AR_VIDS[idx] = 0 - 1
    AR_COUNT = AR_COUNT + 1
    idx
}

fn expr_sin(child: i64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 7  // TAG_SIN
    AR_LEFT[idx] = child
    AR_RIGHT[idx] = 0 - 1
    AR_VALS[idx] = 0.0
    AR_VIDS[idx] = 0 - 1
    AR_COUNT = AR_COUNT + 1
    idx
}

fn expr_cos(child: i64) -> i64 with Mut, Panic {
    let idx = AR_COUNT
    AR_TAGS[idx] = 8  // TAG_COS
    AR_LEFT[idx] = child
    AR_RIGHT[idx] = 0 - 1
    AR_VALS[idx] = 0.0
