fn main() -> i64 with IO, Mut, Div, Panic {
    println("=== Symbolic Differentiation Tests ===")
    println("")

    var passed: i64 = 0
    var failed: i64 = 0

    print("T1: eval(2*x+3) at x=5 = 13 ... ")
    if test_eval_linear() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("T2: d/dx(x^2) = 2x ............ ")
    if test_diff_x_squared() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("T3: d/dx(sin(x)) = cos(x) ..... ")
    if test_diff_sin() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("T4: d/dx(exp(x)) = exp(x) ..... ")
    if test_diff_exp() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("T5: product rule x*sin(x) ..... ")
    if test_product_rule() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    println("")
    print("Passed: ")
    println(passed)
    print("Failed: ")
    println(failed)

    if failed > 0 {
        println("SOME TESTS FAILED")
        return 1
    }
    println("ALL 5 TESTS PASSED")
    return 0
}

