struct Pair { x: i64, y: i64 }
trait R { fn radd(self, o: Self) -> Self; fn rsub(self, o: Self) -> Self }
impl R for i64 { fn radd(self, o: Self) -> Self { self + o } fn rsub(self, o: Self) -> Self { self - o } }
impl R for Pair { fn radd(self, o: Self) -> Self { Pair { x: self.x + o.x, y: self.y + o.y } } fn rsub(self, o: Self) -> Self { Pair { x: self.x - o.x, y: self.y - o.y } } }
fn compute<F: R>(a: F, b: F) -> F { a.radd(b) }
fn combine<F: R>(a: F, b: F, c: F) -> F { let intermediate = compute::<F>(a, b); intermediate.rsub(c) }
fn main() -> i32 with IO, Mut, Panic {
    let p1 = Pair { x: 4, y: 5 }
    let p2 = Pair { x: 2, y: 2 }
    let p3 = Pair { x: 1, y: 1 }
    let res_p = combine::<Pair>(p1, p2, p3)
    println(res_p.x)
    println(res_p.y)
    println("multi_call PASS Pair")
    0
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout-contains: TUPLE_MULTI_BOX_OK
// A function returning a tuple with SEVERAL Box slots must have every slot typed by
// the callee's declared return, not only the first. A and B put the same field names
// at different indices, so a field read that falls back to resolving by NAME reads the
// wrong offset for whichever slot was left untyped.

struct A {
    x: i64,
    y: i64,
}

struct B {
    y: i64,
    x: i64,
}

struct C {
    z: i64,
    w: i64,
}

struct Maker {
    k: i64,
}

// Two Box slots: the second one used to lose its layout.
fn make_pair() -> (Box<A>, Box<B>) with Alloc {
    (Box::new(A { x: 1, y: 2 }), Box::new(B { y: 10, x: 20 }))
}

// Box slots that are not first, with plain slots in between.
fn make_gapped() -> (i64, Box<A>, i64, Box<B>, Box<C>) with Alloc {
    (7, Box::new(A { x: 3, y: 4 }), 8, Box::new(B { y: 30, x: 40 }), Box::new(C { z: 100, w: 200 }))
}

impl Maker {
    // Method-call binding takes a separate path from a plain call.
    fn pair(self: &Maker) -> (Box<B>, Box<A>) with Alloc {
        (Box::new(B { y: 50, x: 60 }), Box::new(A { x: 5, y: 6 }))
    }
}

fn check(bad: i64, got: i64, want: i64) -> i64 with IO, Mut, Panic, Div {
    if got != want {
        print("MISMATCH got=")
        print_int(got)
        print(" want=")
        print_int(want)
        print("\n")
        return bad + 1
    }
    bad
}

fn main() -> i64 with IO, Mut, Panic, Div, Alloc {
    var bad: i64 = 0

    let p = make_pair()
    let pa = p.0
    let pb = p.1
    bad = check(bad, pa.x, 1)
    bad = check(bad, pa.y, 2)
    bad = check(bad, pb.y, 10)
    bad = check(bad, pb.x, 20)

    let g = make_gapped()
    let gn0 = g.0
    let ga = g.1
    let gn2 = g.2
    let gb = g.3
    let gc = g.4
    bad = check(bad, gn0, 7)
    bad = check(bad, ga.x, 3)
    bad = check(bad, ga.y, 4)
    bad = check(bad, gn2, 8)
    bad = check(bad, gb.y, 30)
    bad = check(bad, gb.x, 40)
    bad = check(bad, gc.z, 100)
    bad = check(bad, gc.w, 200)

    let m = Maker { k: 1 }
    let mp = m.pair()
    let mb = mp.0
    let ma = mp.1
    bad = check(bad, mb.y, 50)
    bad = check(bad, mb.x, 60)
    bad = check(bad, ma.x, 5)
    bad = check(bad, ma.y, 6)

    if bad == 0 {
        print("TUPLE_MULTI_BOX_OK\n")
        return 0
    }
    print("TUPLE_MULTI_BOX_FAIL\n")
    1
}

//@ run-pass
//@ expect-stdout: type-hash 3-level PASS
// Regression for the i64 type-hash overflow on 3-level pointer nesting
// (closed in 2523ee2f4 by composite-type interning in lean_single.sio).
//
// Pre-fix: ref_hash_make compounded the inner hash by *256 per level while
// the inner still carried the 2^50 band, so &Option<Box<Struct>> wrapped
// mod 2^64 and corrupted the struct hash — field access reported
// "unknown field" and shapes collided.
//
// Post-fix: composite inners are interned (CT_INNER_HASH[4096]) and only
// a small surrogate id is multiplied, keeping the encoded hash inside
// [2^50, 2^51) at arbitrary depth.
//
// This fixture exercises field access through two structurally distinct
// 3-level nestings simultaneously to assert they do not alias: the same
// compile unit creates and reads both &Option<Box<A>> and &Option<Box<B>>.
// Under the bug, the two struct hashes would collide after the ×256 wrap
// (different inner structs, same wrapped surrogate), so the field offsets
// would be wrong for at least one of them.

struct A { x: i64, y: i64 }
struct B { p: i64, q: i64, r: i64 }

fn read_a(slot: &Option<Box<A>>) -> i64 with Mut, Panic, Div {
    match *slot {
        Some(n) => (*n).x + (*n).y,
        None => 0 - 1,
    }
}

fn read_b(slot: &Option<Box<B>>) -> i64 with Mut, Panic, Div {
    match *slot {
        Some(n) => (*n).p + (*n).q + (*n).r,
        None => 0 - 1,
    }
}

fn main() -> i64 with IO, Mut, Panic, Div, Alloc {
    let ba = Box::new(A { x: 10, y: 20 })
    let ha: Option<Box<A>> = Some(ba)

    let bb = Box::new(B { p: 100, q: 200, r: 300 })
    let hb: Option<Box<B>> = Some(bb)

    let va = read_a(&ha)
    let vb = read_b(&hb)

    assert(va == 30)
    assert(vb == 600)

    // The deepest nesting: read across two distinct 3-level types in the
    // same translation unit. Pre-fix the hash collision would corrupt at
    // least one of the field reads; post-fix both decode cleanly.
    print("type-hash 3-level PASS\n")
    0
}

