// TEST FUNCTIONS
// ============================================================================

// Test 1: Haar roundtrip on constant signal — exact reconstruction within 0.0001
fn test_roundtrip_constant() -> bool with IO, Mut, Panic, Div {
    var sig: [f64; 512] = [0.0; 512]
    var i: i64 = 0
    while i < 64 {
        sig[i as usize] = 5.0
        i = i + 1
    }
    var approx: [f64; 256] = [0.0; 256]
    var detail: [f64; 256] = [0.0; 256]
    let half = haar_forward(sig, 64, &! approx, &! detail)
    var recon: [f64; 512] = [0.0; 512]
    let _len = haar_inverse(approx, detail, half, &! recon)
    i = 0
    while i < 64 {
        if abs_f64(recon[i as usize] - 5.0) > 0.0001 { return false }
        i = i + 1
    }
    return true
}

// Test 2: Haar roundtrip on linear signal [0, 1, 2, ..., 31]
fn test_roundtrip_linear() -> bool with IO, Mut, Panic, Div {
    var sig: [f64; 512] = [0.0; 512]
    var i: i64 = 0
    while i < 32 {
        sig[i as usize] = i as f64
        i = i + 1
    }
    var approx: [f64; 256] = [0.0; 256]
    var detail: [f64; 256] = [0.0; 256]
    let half = haar_forward(sig, 32, &! approx, &! detail)
    var recon: [f64; 512] = [0.0; 512]
    let _len = haar_inverse(approx, detail, half, &! recon)
    i = 0
    while i < 32 {
        if abs_f64(recon[i as usize] - (i as f64)) > 0.0001 { return false }
        i = i + 1
    }
    return true
}

// Test 3: Energy preserved — ||signal||^2 = ||approx||^2 + ||detail||^2
fn test_energy_preserved_constant() -> bool with IO, Mut, Panic, Div {
    var sig: [f64; 512] = [0.0; 512]
    var i: i64 = 0
    while i < 16 {
        sig[i as usize] = 3.0
        i = i + 1
    }
    let e_before = energy_512(sig, 16)  // 16 * 9 = 144
    var approx: [f64; 256] = [0.0; 256]
    var detail: [f64; 256] = [0.0; 256]
    let half = haar_forward(sig, 16, &! approx, &! detail)
    let e_after = energy_256(approx, half) + energy_256(detail, half)
    return abs_f64(e_before - e_after) / e_before < 1.0e-10
}

// Test 4: Energy preserved on a mixed signal
fn test_energy_preserved_mixed() -> bool with IO, Mut, Panic, Div {
    var sig: [f64; 512] = [0.0; 512]
    var i: i64 = 0
    while i < 64 {
        if i % 2 == 0 {
            sig[i as usize] = (i as f64) * 0.1 + 1.0
        } else {
            sig[i as usize] = 0.0 - ((i as f64) * 0.05 + 0.5)
        }
        i = i + 1
    }
    let e_before = energy_512(sig, 64)
    var approx: [f64; 256] = [0.0; 256]
    var detail: [f64; 256] = [0.0; 256]
    let half = haar_forward(sig, 64, &! approx, &! detail)
    let e_after = energy_256(approx, half) + energy_256(detail, half)
    if e_before < 1.0e-15 { return true }
    return abs_f64(e_before - e_after) / e_before < 1.0e-10
}

// Test 5: Alternating signal has zero approximation and nonzero detail
fn test_alternating_all_detail() -> bool with IO, Mut, Panic, Div {
    var sig: [f64; 512] = [0.0; 512]
    var i: i64 = 0
    while i < 16 {
        if i % 2 == 0 { sig[i as usize] = 2.0 } else { sig[i as usize] = 0.0 - 2.0 }
        i = i + 1
    }
    var approx: [f64; 256] = [0.0; 256]
    var detail: [f64; 256] = [0.0; 256]
    let half = haar_forward(sig, 16, &! approx, &! detail)
    // Constant pairs cancel → all approx should be 0
    i = 0
    while i < half {
        if abs_f64(approx[i as usize]) > 1.0e-12 { return false }
        i = i + 1
    }
    // Detail should be nonzero
    let e_detail = energy_256(detail, half)
    return e_detail > 1.0
}

// Test 6: SNR of perfect reconstruction is very high (> 200 dB)
// IEEE 754 double accumulates ~1e-16 relative error per multiply,
// giving ~300 dB in practice for this signal.
fn test_snr_perfect_reconstruction() -> bool with IO, Mut, Panic, Div {
    var sig: [f64; 512] = [0.0; 512]
    var i: i64 = 0
    while i < 32 {
        sig[i as usize] = (i as f64) * 0.5 + 1.0
        i = i + 1
    }
    var approx: [f64; 256] = [0.0; 256]
    var detail: [f64; 256] = [0.0; 256]
    let half = haar_forward(sig, 32, &! approx, &! detail)
    var recon: [f64; 512] = [0.0; 512]
    let _len = haar_inverse(approx, detail, half, &! recon)
    let snr = snr_512(sig, recon, 32)
    return snr > 200.0
}

// ============================================================================
// MAIN
// ============================================================================

fn run_tests(dummy: i64) -> i32 with IO, Mut, Panic, Div {
    var passed = 0
    var failed = 0

    print("Test 1: Haar roundtrip constant signal (err < 0.0001) . ")
    if test_roundtrip_constant() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("Test 2: Haar roundtrip linear signal [0..31] .......... ")
    if test_roundtrip_linear() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("Test 3: Energy preserved: E_sig = E_approx + E_detail . ")
    if test_energy_preserved_constant() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("Test 4: Energy preserved on mixed signal ............... ")
    if test_energy_preserved_mixed() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("Test 5: Alternating signal → all detail, zero approx .. ")
    if test_alternating_all_detail() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    print("Test 6: SNR of perfect reconstruction > 200 dB ........ ")
    if test_snr_perfect_reconstruction() {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    println("")
    print("Passed: ")
    println(passed)
    print("Failed: ")
    println(failed)

    if failed > 0 {
        println("SOME TESTS FAILED")
        return 1
    }
    println("ALL TESTS PASSED")
    return 0
}

fn main() -> i32 with IO, Mut, Panic, Div {
    println("=== Haar Wavelet Roundtrip & Energy Preservation Tests ===")
    println("")
    return run_tests(0)
}

//@ run-pass
//@ requires: madaros
//@ exit-code: 0
//@ description: machine-unlearning with a 4-generator contribution — the old 2-of-4 projection leaves g1/g2 residual, the fixed stdlib forget_contribution (4-of-4) erases it exactly
// Full Test Suite CI uses souc-stage2 (lean_single). Madaros runs this graph.
//
// examples/zd_machine_unlearning.sio uses an INLINE 2-vector projection (g0,g3)
// and places Alice only on those two generators, so it never exercises the full
// kernel. This test constructs a contribution that spans all four generators and
// shows the difference the #2111 fix makes:
//   OLD (2-of-4, replicated inline): Alice's g1/g2 components SURVIVE forgetting.
//   NEW (stdlib forget_contribution): the whole contribution is erased, exact.
// Integer coefficients ⇒ exact comparisons.

use algebra::sedenion::{sed_norm_sq}
use privacy::exactly_private::{forget_contribution}

fn main() -> i64 with IO, Mut, Div, Panic, ZD {
    var ok: i64 = 1

    // kernel generators
    var g0: [f64; 16] = [0.0; 16]; g0[6] = 1.0;  g0[15] = 0.0 - 1.0
    var g1: [f64; 16] = [0.0; 16]; g1[4] = 1.0;  g1[13] = 1.0
    var g2: [f64; 16] = [0.0; 16]; g2[5] = 1.0;  g2[12] = 0.0 - 1.0
    var g3: [f64; 16] = [0.0; 16]; g3[7] = 1.0;  g3[14] = 1.0

    // Bob = retained model (non-kernel), Alice = user contribution across ALL 4
    // generators: 3 g0 + 2 g1 + 5 g2 + 1 g3. W_full = Bob + Alice.
    var bob: [f64; 16] = [0.0; 16]; bob[0] = 1.0            // e0, non-kernel
    var w_full: [f64; 16] = [0.0; 16]
    var i: i64 = 0
    while i < 16 {
        w_full[i] = bob[i] + 3.0*g0[i] + 2.0*g1[i] + 5.0*g2[i] + 1.0*g3[i]
        i = i + 1
    }

    // OLD method (2-of-4): project out only g0 and g3 (g_k·g_k = 2 ⇒ ·0.5).
    var c0 = 0.0; var c3 = 0.0
    i = 0
    while i < 16 { c0 = c0 + w_full[i]*g0[i]; c3 = c3 + w_full[i]*g3[i]; i = i + 1 }
    c0 = c0 * 0.5; c3 = c3 * 0.5
    var old_forget: [f64; 16] = [0.0; 16]
    i = 0
    while i < 16 { old_forget[i] = w_full[i] - c0*g0[i] - c3*g3[i]; i = i + 1 }
    // residual vs Bob = what the OLD method failed to forget (should be 2 g1 + 5 g2)
    var old_leak: [f64; 16] = [0.0; 16]
    i = 0
    while i < 16 { old_leak[i] = old_forget[i] - bob[i]; i = i + 1 }
    let old_leak_nsq = sed_norm_sq(&old_leak)   // 2 g1 + 5 g2: 2·(4) + 2·(25) = 58

    // NEW method: the fixed 4-of-4 stdlib forget.
    let new_forget = forget_contribution(&w_full)
    var new_leak: [f64; 16] = [0.0; 16]
    i = 0
    while i < 16 { new_leak[i] = new_forget[i] - bob[i]; i = i + 1 }
    let new_leak_nsq = sed_norm_sq(&new_leak)   // exactly Bob recovered ⇒ 0

    print("OLD (2-of-4) leak nsq = "); print(old_leak_nsq); print("  (g1/g2 survive)\n")
    print("NEW (4-of-4) leak nsq = "); print(new_leak_nsq); print("  (exact erasure)\n")

    // the bug: old method leaves exactly 2 g1 + 5 g2 (norm² 58)
    if old_leak_nsq != 58.0 { ok = 0 }
    // the fix: nothing of Alice survives
    if new_leak_nsq != 0.0 { ok = 0 }

    if ok == 1 {
        print("ZD UNLEARNING FULL-BASIS: fix erases 4-generator contribution PASS\n")
        0
    } else {
        print("ZD UNLEARNING FULL-BASIS FAIL\n")
        1
    }
}

